package com.lolfm.simulator;
import java.util.EnumMap;
public final class LateGameExecutionStats{private int transitions,evaluations,duplicates,noInitiative,initiativeRolls,planRolls,responseRolls,attempts,fights,structures,crossMapAttempts,crossMapSuccess,nexusFinishAttempts,nexusDestroyed;private final EnumMap<LateGameTransitionReason,Integer> transitionReasons=new EnumMap<>(LateGameTransitionReason.class);void transition(LateGameTransitionReason r){transitions++;transitionReasons.merge(r,1,Integer::sum);}void evaluation(){evaluations++;}void duplicate(){duplicates++;}void noInitiative(){noInitiative++;}void initiativeRoll(){initiativeRolls++;}void planRoll(){planRolls++;}void responseRoll(){responseRolls++;}void attempt(){attempts++;}void fight(){fights++;}void structure(){structures++;}void crossMap(boolean success){crossMapAttempts++;if(success)crossMapSuccess++;}void finishAttempt(){nexusFinishAttempts++;}void nexusDestroyed(){nexusDestroyed++;}public LateGameExecutionStatsSnapshot snapshot(){return new LateGameExecutionStatsSnapshot(transitions,transitionReasons,evaluations,duplicates,noInitiative,initiativeRolls,planRolls,responseRolls,attempts,fights,structures,crossMapAttempts,crossMapSuccess,nexusFinishAttempts,nexusDestroyed);}}
